class Solution {
public:
    void nextPermutation(vector<int>& nums) {
        int i = (int)nums.size() - 2;
        while (i >= 0 && nums[i] >= nums[i + 1]) {      // 从右往左找第一个下降
            i--;
        }
        if (i >= 0) {
            int j = (int)nums.size() - 1;
            while (nums[j] <= nums[i]) {                // 右边第一个比 nums[i] 大的
                j--;
            }
            swap(nums[i], nums[j]);
        }
        int l = i + 1, r = (int)nums.size() - 1;        // 右段反转成升序
        while (l < r) {
            swap(nums[l++], nums[r--]);
        }
    }
};

